let profile,projects,papers,media;
const esc=x=>String(x??'').replace(/[&<>"']/g,c=>({"&":"&amp;","<":"&lt;",">":"&gt;",'"':"&quot;","'":"&#39;"}[c]));
const safe=u=>{u=String(u||'');return /^(https?:\/\/|mailto:|\/(?!\/)|#)/i.test(u)?u:'#'};
const repo=p=>'https://github.com/eddiekhae/'+p.repo;const raw=(p,f)=>'https://raw.githubusercontent.com/eddiekhae/'+p.repo+'/main/'+encodeURIComponent(f);const a=(href,label,cls='')=>`<a href="${esc(safe(href))}" class="${esc(cls)}">${esc(label)}</a>`;const sub=(title,href,links)=>`<details><summary>${title}</summary><div class="dropdown">${a(href,'Overview')}${links.map(l=>a(l[0],l[1])).join('')}</div></details>`;
function header(){return `<header>${a('/',profile.name.toUpperCase(),'brand')}<button class="menu-toggle" aria-expanded="false" aria-controls="navigation">Menu</button><nav id="navigation" aria-label="Main navigation">${a('/','Home')}${a('/about/','About')}${sub('CV','/cv/',[['/cv/#full','Full version'],['/cv/#short','Short version']])}${sub('Data','/data/',projects.map(p=>['/data/'+p.slug+'/',p.title]))}${sub('Media','/media/',['All','Economic history','International trade','Industrial economics','Miscellaneous'].map(c=>['/media/?category='+encodeURIComponent(c),c]))}${sub('Research','/research/',[['/research/published/','Published papers'],['/research/working/','Working papers'],['/research/projects/','Research projects']])}</nav></header>`}
const footer=()=>`<footer><span>© ${new Date().getFullYear()} ${esc(profile.name)}</span><span>${a(profile.github,'GitHub')}${a(profile.linkedin,'LinkedIn')}${a('mailto:'+profile.email,'Email')}</span></footer><button class="top" aria-label="Scroll to top">↑</button>`;
const banner=t=>`<section class="page-banner"><h1>${t}</h1></section>`;const empty=t=>`<div class="empty">${t}</div>`;
function home(){return `<section class="hero"><div class="hero-content"><h1>${esc(profile.name)}</h1><p>${profile.interests.map(esc).join("<br>")}</p>${a('/research/projects/','Explore my research','button')}</div>${a('#explore','⌄','down')}</section><section id="explore" class="section cards">${a('/cv/','View CV','tile')}${a('/data/','View Data','tile')}${a('/research/','View Research','tile')}</section><section class="section bio"><div><span class="eyebrow">Who I Am</span><h2>${esc(profile.introduction)}</h2><p>${esc(profile.bio[0])}</p><p>${esc(profile.bio[1])}</p>${a('/about/','More about me','button')}</div>${portrait()}</section><section class="section"><h2>Recent Media</h2>${media.length?mediaEntries(media.slice(0,3)):empty('Media coverage will appear here when available.')}</section>`}
function render(){const path=location.pathname;let body='';if(path==='/')body=home();else if(path==='/about/')body=banner('About')+`<main class="page-content"><div class="bio" style="background:white"><div><h2>Who I Am</h2>${profile.bio.map(p=>'<p>'+esc(p)+'</p>').join('')}${a(profile.github,'GitHub profile','button')}</div>${portrait()}</div></main>`;else if(path==='/cv/')body=banner('CV')+`<main class="page-content"><h2>Academic background</h2>${profile.education.map(x=>'<div class="entry">'+esc(x)+'</div>').join('')}<h2>Research & teaching experience</h2>${profile.experience.map(x=>'<div class="entry">'+esc(x)+'</div>').join('')}<h2 id="full">Full CV</h2>${profile.full_cv?a(profile.full_cv,'Download full CV','button'):empty('A downloadable full CV has not yet been added.')}<h2 id="short">Short CV</h2>${profile.short_cv?a(profile.short_cv,'Download short CV','button'):empty('A downloadable short CV has not yet been added.')}</main>`;else if(path==='/data/')body=banner('Data')+`<main class="page-content"><p>Datasets, research code, and replication resources.</p>${projects.map(p=>`<article class="entry"><span class="eyebrow">${esc(p.category)}</span><h2>${a('/data/'+p.slug+'/',p.title)}</h2><p>${esc(p.description)}</p>${a('/data/'+p.slug+'/','View resources')}</article>`).join('')}</main>`;else if(path.startsWith('/data/')){const p=projects.find(p=>path==='/data/'+p.slug+'/');body=p?banner(p.title)+`<main class="page-content"><h2>Replication resources</h2><p>${esc(p.description)}</p>${p.citation?'<p>Citation: '+esc(p.citation)+'</p>':''}${projectImage(p)}${(p.files||[]).map(f=>`<div class="entry">${a(raw(p,f),f)} <span class="muted"> · ${f.split('.').pop().toUpperCase()}</span></div>`).join('')}${attachments(p.attachments)}${p.repo?'<p>'+a(repo(p),'View complete repository','button')+'</p>':''}<p>${a('/data/','All research resources')}</p></main>`:banner('Page not found')+`<main class="page-content">${a('/','Return home')}</main>`}else if(path.startsWith('/research/')){const published=path.includes('/published'),working=path.includes('/working');body=banner(published?'Published Papers':working?'Working Papers':'Research')+`<main class="page-content"><div class="filters">${a('/research/published/','Published papers','button')}${a('/research/working/','Working papers','button')}${a('/research/projects/','Research projects','button')}</div>${published?paperEntries('Published'):working?paperEntries('Working'):projects.map(p=>`<article class="entry"><span class="eyebrow">${p.category}</span><h2>${esc(p.title)}</h2><p>${esc(p.description)}</p><div class="file-links">${p.repo?a(repo(p),'Project repository'):''}${a('/data/'+p.slug+'/','Replication resources')}${p.repo==='DSGE-models'?a(raw(p,'Final Report.pdf'),'Read project report (PDF)'):''}</div></article>`).join('')}</main>`}else if(path==='/media/'){let selected=new URLSearchParams(location.search).get('category')||'All';body=banner('Media')+`<main class="page-content"><div class="filters">${['All','Economic history','International trade','Industrial economics','Miscellaneous'].map(c=>`<button class="${c===selected?'active':''}" data-category="${c}" aria-pressed="${c===selected}">${c}</button>`).join('')}</div>${mediaEntries(media.filter(m=>selected==='All'||m.category===selected))}</main>`}else body=banner('Page not found')+`<main class="page-content">${a('/','Return home')}</main>`;document.querySelector('#app').innerHTML=header()+body+footer();document.title=(path==='/'?profile.name:document.querySelector('h1').textContent+' | '+profile.name);document.documentElement.style.setProperty('--hero-image','url("'+safe(profile.hero).replace(/["\\]/g,'')+'")');document.querySelector('.menu-toggle').onclick=e=>{let open=document.querySelector('nav').classList.toggle('open');e.currentTarget.setAttribute('aria-expanded',open);e.currentTarget.textContent=open?'Close':'Menu'};document.querySelector('.top').onclick=()=>window.scrollTo({top:0,behavior:'smooth'});document.querySelectorAll('[data-category]').forEach(b=>b.onclick=()=>{history.pushState({},'','/media/?category='+encodeURIComponent(b.dataset.category));render()});document.querySelectorAll('details').forEach(d=>d.addEventListener('toggle',()=>{if(d.open)document.querySelectorAll('details').forEach(other=>{if(other!==d)other.open=false})}));}
function portrait(){return profile.portrait?'<img class="profile-image" src="'+esc(safe(profile.portrait))+'" alt="'+esc(profile.name)+'">':'<div class="identity-panel"><span class="identity-monogram" aria-hidden="true">'+esc(profile.name.split(' ').map(n=>n[0]).slice(0,2).join(''))+'</span><p>'+esc(profile.name)+'</p><span>Economics · Research · Teaching</span></div>'}
function projectImage(p){return p.image?'<img class="project-image" src="'+esc(safe(p.image))+'" alt="'+esc(p.title)+'">':''}
function attachments(list=[]){return list.map(f=>'<div class="entry">'+a(f.file||f.url,f.label||'Download file')+'</div>').join('')}
function paperEntries(status){const list=papers.filter(p=>p.status===status);return list.length?list.map(p=>'<article class="entry"><h2>'+esc(p.title)+'</h2><p>'+esc(p.authors||'')+'</p><p class="muted">'+esc(p.publication||'')+'</p><p>'+esc(p.abstract||'')+'</p>'+projectImage(p)+attachments(p.attachments)+(p.pdf?a(p.pdf,'Read paper (PDF)','button'):'')+(p.url?'<p>'+a(p.url,'Publication link')+'</p>':'')+'</article>').join(''):empty('No '+status.toLowerCase()+' papers have been added yet.')}
function mediaEntries(list){return list.length?list.map(m=>'<article class="entry"><span class="eyebrow">'+esc(m.category)+'</span><h3>'+a(m.url,m.title)+'</h3><p class="muted">'+esc(m.date||'')+'</p>'+projectImage(m)+'</article>').join(''):empty('No media coverage has been added in this category yet.')}
fetch('/content.json',{cache:'no-store'}).then(r=>{if(!r.ok)throw Error('Content unavailable');return r.json()}).then(data=>{profile=data.profile;projects=data.projects||[];papers=data.papers||[];media=data.media||[];render()}).catch(()=>{document.querySelector('#app').textContent='The website content could not be loaded. Please refresh.'});window.addEventListener('popstate',render);document.addEventListener('keydown',e=>{if(e.key==='Escape'){document.querySelectorAll('details').forEach(d=>d.open=false);document.querySelector('nav').classList.remove('open');document.querySelector('.menu-toggle').setAttribute('aria-expanded','false');document.querySelector('.menu-toggle').textContent='Menu'}});
